# Extract ExtTex / Unknown1 from Cleaning Robot SCFU raw body
hexbody = ""
# Find Material marker
idx = hexbody.find("4D6174657269616C")  # "Material"
print("Material at", idx)
# Walk back for length prefix - typically 4 bytes before string in AO: 000007E2 or 00000BD3
start = idx - 4
chunk = hexbody[start:start+96]
print("chunk", chunk)
b = bytes.fromhex(chunk)
print("bytes", list(b))
print("as csharp:", ", ".join(str(x) for x in b[:48]))

# Unknown1 from csv: 80000000000000000000000003010001000100010001000000020000
u1 = bytes.fromhex("80000000000000000000000003010001000100010001000000020000")
print("u1", list(u1))
